/**
 * DOM Events
 * ==========
 *
 * DOM events are notifications generated by user interactions or browser
 * environment changes. JavaScript registers listeners to execute handlers
 * when these events occur.
 */

// ---------------------------------------------------------------------
// 1. Adding and removing event listeners
// ---------------------------------------------------------------------

const button = document.querySelector("#save-button");

function handleClick(event) {
  // Handle click
}

button.addEventListener("click", handleClick);
// Requires the exact same function reference to remove:
button.removeEventListener("click", handleClick);

// Anonymous functions cannot be removed later because they lack a reference.
button.addEventListener("click", () => {});
// button.removeEventListener("click", () => {}); // Does not work!

// ---------------------------------------------------------------------
// 2. Event properties (target and currentTarget)
// ---------------------------------------------------------------------

button.addEventListener("click", (event) => {
  event.type; // "click"
  const target = event.target; // Where the event originated
  const currentTarget = event.currentTarget; // Whose listener is executing
});

// ---------------------------------------------------------------------
// 3. Common DOM events
// ---------------------------------------------------------------------

// Mouse events
button.addEventListener("dblclick", () => {});
button.addEventListener("mousedown", () => {});
button.addEventListener("mouseup", () => {});
button.addEventListener("mouseenter", () => {});

// Keyboard events
const input = document.querySelector("#search");
input.addEventListener("keydown", (event) => {
  event.key; // Logical key value (e.g., "Enter")
  event.code; // Physical key (e.g., "KeyA")
  event.ctrlKey; // Modifier state
});

// Form and input events
input.addEventListener("input", (event) => {
  const value = event.target.value;
});
input.addEventListener("change", (event) => {
  // Committed value change
});
input.addEventListener("focus", () => {});
input.addEventListener("blur", () => {});

const form = document.querySelector("#profile-form");
form.addEventListener("submit", (event) => {
  event.preventDefault(); // Prevents default browser navigation/submission
});

// ---------------------------------------------------------------------
// 4. Event listener options
// ---------------------------------------------------------------------

button.addEventListener("click", handleClick, {
  capture: true, // Participate during capture phase
  once: true, // Automatically removed after first invocation
});

window.addEventListener("scroll", () => {}, {
  passive: true, // Signals that preventDefault() will not be called (optimizes performance)
});

// ---------------------------------------------------------------------
// 5. AbortController for event listeners
// ---------------------------------------------------------------------

const controller = new AbortController();
button.addEventListener("click", handleClick, { signal: controller.signal });
controller.abort(); // Automatically removes the event listener

// ---------------------------------------------------------------------
// 6. Context (`this` vs. arrow functions)
// ---------------------------------------------------------------------

button.addEventListener("click", function (event) {
  this === event.currentTarget; // true for standard functions
});

button.addEventListener("click", (event) => {
  // `this` is lexically bound and does not refer to event.currentTarget
});

// ---------------------------------------------------------------------
// 7. Window, Document, and Custom events
// ---------------------------------------------------------------------

window.addEventListener("resize", () => {});
window.addEventListener("online", () => {});
window.addEventListener("offline", () => {});

document.addEventListener("DOMContentLoaded", () => {
  // HTML document parsed
});

// Custom events with application data
const customEvent = new CustomEvent("user-selected", {
  detail: { userId: 42 },
});
document.dispatchEvent(customEvent);

document.addEventListener("user-selected", (event) => {
  event.detail.userId; // 42
});

// ---------------------------------------------------------------------
// Summary
// ---------------------------------------------------------------------
// - DOM events allow JavaScript to respond to user actions and browser environment changes.
// - `addEventListener()` registers handlers, requiring identical references for `removeEventListener()`.
// - `event.target` represents the origin of the event, while `event.currentTarget` points to the element whose listener is running.
// - Use `event.preventDefault()` to cancel default browser behaviors like form submissions.
// - Listener options like `once`, `passive`, and `AbortController` signals optimize and simplify event management.
// - Custom events enable modular communication via `CustomEvent` and `dispatchEvent()`.
